import { describe, it } from "vitest";

describe("claim", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 -> payout 400, remaining cap 1600");
  it.todo("rune, damage 200 -> payout 100 (no special clause), remaining cap 400");
  it.todo("damage below the deductible -> payout 0 (chosen reading: payout never negative)");
  it.todo("dragon sword, enchantment 5, damage 800 -> payout 700 (full reimbursement)");
  it.todo("steel sword, enchantment 9, damage 1000 -> payout 400 (50 % first, then deductible)");
  it.todo("steel sword, enchantment 7, damage 1000 -> payout 900 (below the enchantment threshold)");
  it.todo("dragon sword, enchantment 9, damage 1000 -> payout 400 (50 % rule wins)");
  it.todo("dragon sword, enchantment exactly 8, damage 1000 -> payout 400");
  it.todo("sword damage 500 + amulet damage 300 -> payout 600 (deductible per damaged item)");
  it.todo("payout calculation yielding 350.5 -> payout 350 (rounded down)");
  it.todo("two swords, two sword damages of 500 -> each has its own deductible: payout 800, remaining cap 3200");
  it.todo("two sword damages but only one sword insured -> claim is rejected with an error");
  it.todo("amulet damaged while only a sword is insured -> claim is rejected with an error");
  it.todo("damage with unknown item type -> claim is rejected with an error");
  it.todo("damage amount -200 -> claim is rejected with an error");
  it.todo("claim refers to a step that is not an existing quote -> rejected with an error (chosen reading)");
  it.todo("claim on the second policy uses that policy's items and cap");
  it.todo("sword + amulet -> insurance sum 1600, cap 3200");
  it.todo("cursed sword -> cap 2000 (premium modifiers do not raise the cap)");
  it.todo("sword + 3 runes -> insurance sum 1750, cap 3500 (block affects premium only)");
  it.todo("two successive claims of 1500 on a sword -> 1400 / cap 600, then 600 / cap 0");
});

