import { basePremium } from "./base-premium.js";

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

const PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;

function quotePremium(items: QuoteItem[]): number {
  const percentOfBase = PERCENT + FIRST_INSURANCE_SURCHARGE_PERCENT;
  return Math.ceil((basePremium(items) * percentOfBase) / PERCENT) + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}

