import { basePremium } from "./base-premium.js";
import type { Item } from "./item.js";
import { BASE_PREMIUM_BY_TYPE } from "./price-list.js";

const PERCENT = 100;
const CURSE_SURCHARGE_PERCENT = 50;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;

function curseSurchargePercentOfG(item: Item): number {
  return item.cursed ? (BASE_PREMIUM_BY_TYPE[item.type] ?? 0) * CURSE_SURCHARGE_PERCENT : 0;
}

export function quotePremium(items: Item[]): number {
  const base = basePremium(items);
  const itemSurcharges = items.reduce((sum, item) => sum + curseSurchargePercentOfG(item), 0);
  const policySurcharge = base * FIRST_INSURANCE_SURCHARGE_PERCENT;
  const premiumInHundredths = base * PERCENT + itemSurcharges + policySurcharge;
  return Math.ceil(premiumInHundredths / PERCENT) + PROCESSING_FEE;
}

