import { basePremium } from "./base-premium.js";
import type { Item } from "./item.js";
import { BASE_PREMIUM_BY_TYPE } from "./price-list.js";

const HUNDREDTHS_PER_G = 100;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function itemSurchargePercent(item: Item): number {
  const curse = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const enchantment = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return curse + enchantment;
}

function itemSurchargeInHundredths(item: Item): number {
  return (BASE_PREMIUM_BY_TYPE[item.type] ?? 0) * itemSurchargePercent(item);
}

export function quotePremium(items: Item[]): number {
  const base = basePremium(items);
  const itemSurcharges = items.reduce((sum, item) => sum + itemSurchargeInHundredths(item), 0);
  const policySurcharge = base * FIRST_INSURANCE_SURCHARGE_PERCENT;
  const premiumInHundredths = base * HUNDREDTHS_PER_G + itemSurcharges + policySurcharge;
  return Math.ceil(premiumInHundredths / HUNDREDTHS_PER_G) + PROCESSING_FEE;
}

