import { describe, expect, it } from "vitest";
import type { Item } from "./item.js";
import { runScenario } from "./scenario.js";

function firstQuotePremium(items: Item[], yearsWithMHPCO = 0): unknown {
  const { results } = runScenario({
    customer: { yearsWithMHPCO },
    steps: [{ op: "quote", items }],
  });
  return results[0];
}

describe("quote", () => {
  it("empty item list -> premium 5 G (only the processing fee)", () => {
    expect(firstQuotePremium([])).toEqual({ premium: 5 });
  });

  it("newcomer, plain amulet -> 60 + 6 first insurance + 5 fee = 71 G", () => {
    expect(firstQuotePremium([{ type: "amulet" }])).toEqual({ premium: 71 });
  });

  it("newcomer, cursed sword (steel, enchantment 3) -> 165 G", () => {
    const cursedSword = { type: "sword", material: "steel", enchantment: 3, cursed: true };
    expect(firstQuotePremium([cursedSword])).toEqual({ premium: 165 });
  });

  it("sword with enchantment 5 -> high-enchantment surcharge: 100 + 30 + 10 + 5 = 145 G", () => {
    expect(firstQuotePremium([{ type: "sword", enchantment: 5 }])).toEqual({ premium: 145 });
  });

  it.todo("sword with enchantment 4 -> no high-enchantment surcharge: 115 G");
  it.todo("cursed sword with enchantment 4 -> curse only: 165 G");
  it.todo("cursed sword with enchantment 5 -> both surcharges: 100 + 50 + 30 + 10 + 5 = 195 G");
  it.todo("customer with exactly 2 years -> loyalty discount: 100 + 10 - 20 + 5 = 95 G");
  it.todo("customer with 1 year -> no loyalty discount: 115 G");
  it.todo("cursed sword + plain amulet, newcomer -> curse on the sword only: 210 + 16 + 5 = 231 G");
  it.todo("loyalty discount applies to the policy base premium: cursed sword + amulet, 3 years -> 199 G");
  it.todo("second quote of a newcomer -> follow-up discount: 100 + 10 - 15 + 5 = 100 G");
  it.todo("third quote also gets the follow-up discount, claim steps do not count as contracts");
  it.todo("long-standing customer's second quote, cursed sword enchantment 7 -> 160 G");
  it.todo("7 runes, newcomer -> 197.5 G rounds up to 198 G");
  it.todo("unknown item type (broomstick) -> quote is rejected with an error");
});

