import type { Item } from "./item.js";
import { riskSurchargeInHundredths } from "./item-risk-surcharge.js";

const HUNDREDTHS_PER_G = 100;
const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_PERCENT = 20;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;

function policyModifierPercent(yearsWithMHPCO: number): number {
  const loyaltyDiscount = yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_DISCOUNT_PERCENT : 0;
  return FIRST_INSURANCE_SURCHARGE_PERCENT - loyaltyDiscount;
}

export function quotePremium(items: Item[], yearsWithMHPCO: number): number {
  const base = basePremium(items);
  const itemSurcharges = items.reduce((sum, item) => sum + riskSurchargeInHundredths(item), 0);
  const policyModifiers = base * policyModifierPercent(yearsWithMHPCO);
