import { INSURANCE_VALUE_BY_TYPE } from "./price-list.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
}

export function processClaim(items: Item[], damages: Damage[]): ClaimResult {
  const payout = damages.reduce((sum, damage) => sum + damage.amount - DEDUCTIBLE, 0);
  return { payout, remainingCap: insuranceSum(items) * CAP_MULTIPLIER - payout };
}

