25	function damagePayout(damage: Damage, items: Item[]): number {
26	  const insuredItem = items.find((item) => item.type === damage.itemType);
27	  return Math.max(0, reimbursedAmount(damage.amount, insuredItem) - DEDUCTIBLE);
28	}
