30	export function processClaim(items: Item[], damages: Damage[]): ClaimResult {
31	  const exactPayout = damages.reduce((sum, damage) => sum + damagePayout(damage, items), 0);
32	  const payout = Math.floor(exactPayout);
33	  return { payout, remainingCap: insuranceSum(items) * CAP_MULTIPLIER - payout };
34	}

