import type { Item } from "./item.js";
import { reimbursedAmount } from "./reimbursement.js";
import { COMPONENT_INSURANCE_VALUE, INSURANCE_VALUE_BY_TYPE } from "./price-list.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

function insuranceSum(items: Item[]): number {
  return items.reduce(
    (sum, item) => sum + (INSURANCE_VALUE_BY_TYPE[item.type] ?? COMPONENT_INSURANCE_VALUE),
    0,
  );
}

function damagePayout(damage: Damage, insuredItem: Item): number {
  return Math.max(0, reimbursedAmount(damage.amount, insuredItem) - DEDUCTIBLE);
}

function matchInsuredItems(items: Item[], damages: Damage[]): Item[] {
  const unmatched = [...items];
  return damages.map((damage) => {
    const index = unmatched.findIndex((item) => item.type === damage.itemType);
    if (index === -1) {
      throw new Error(`No insured ${damage.itemType} left to claim for`);
    }
    return unmatched.splice(index, 1)[0];
  });
}

export function processClaim(items: Item[], damages: Damage[]): ClaimResult {
  const insuredItems = matchInsuredItems(items, damages);
  const exactPayout = damages.reduce(
    (sum, damage, index) => sum + damagePayout(damage, insuredItems[index]),
    0,
  );
  const payout = Math.floor(exactPayout);
  return { payout, remainingCap: insuranceSum(items) * CAP_MULTIPLIER - payout };
}

